void init_ad(int pines) {
    TRISB |= pines & 0x3F >> 2;
    TRISA |= pines & 3;
    AD1PCFGL = ~pines;
    AD1CON3 = 0x105;        // SAMC = 1, ADCS = 5 -> 1 ciclo de muestreo
    AD1CON2 = 0;
    AD1CON1 = 0x80E0;       // ADON, SSRC = 111
}

int get_ad(int pin) {
    AD1CHS0 = pin;              // selecciona pin de conversión
    IFS0bits.AD1IF = 0;
    AD1CON1bits.SAMP = 1;       // comienza
    while (!IFS0bits.AD1IF);    // conversión terminada?
    return ADC1BUF0;
}

#include "config.h"

void init_ad(int canales) {
    TRISB |= canales & 0x3F >> 2;
    TRISA |= canales & 3;
    AD1PCFGL = ~canales;
    AD1CON3 = 0x105;
    AD1CON2 = 0;
    AD1CON1 = 0x80E0;
}

int get_ad(int canal) {
    AD1CHS0 = canal;
    AD1CON1bits.SAMP = 1;
    IFS0bits.AD1IF = 0;
    while (!IFS0bits.AD1IF);
    return ADC1BUF0;
}

int main(void) {
    InicializarReloj();
    PORTB = 0xFFFF;
    TRISB = 0x0FFF;
    init_ad(0x20);          // canal 5
    while (1)
        PORTB = (get_ad(5) << 6) & 0xF000;
    return 0;
}

void init_ad(int pines, int n_pines) {
    TRISB |= pines & 0x3F >> 2;
    TRISA |= pines & 3;
    AD1PCFGL = ~pines;
    AD1CSSL = pines;
    AD1CON3 = 0x0105;                       // SAMC = 1, ADCS = 5 -> 1 ciclo de muestreo
    AD1CON2 = 0x0400 | (n_pines-1 << 2);    // CSCNA, SMPI escaneo
    AD1CON1 = 0x80E4;                       // ADON, SSRC = 111, ASAM = 1.
}

volatile int m_vi_valores[6];
int m_n_pines;

void init_ad(int pines, int n_pines) {
    m_n_pines = n_pines;
    TRISB |= pines & 0x3F >> 2;
    TRISA |= pines & 3;
    AD1PCFGL = ~pines;
    AD1CSSL = pines;
    AD1CON3 = 0x0105;                       // SAMC = 1, ADCS = 5 -> 1 ciclo de muestreo
    AD1CON2 = 0x0400 | (n_pines-1 << 2);    // CSCNA, SMPI escaneo
    AD1CON1 = 0x80E4;                       // ADON, SSRC = 111, ASAM = 1.
    IFS0bits.AD1IF = 0;     // Borrar la bandera de la interrupción
    IEC0bits.AD1IE = 1;     // Habilitar las interrupciones del conversor A/D
    IPC3bits.AD1IP = 1;     // Prioridad de la interrupción (máx. 7 - mín. 1)
}

void __attribute__((interrupt, no_auto_psv)) _ADC1Interrupt(void) {
    IFS0bits.AD1IF = 0;     // Borrar la bandera de la interrupción
    int *pBuf = 0x300;      // dirección de ADC1BUF0
    for (int i = 0; i < m_n_pines; i++)
        m_vi_valores[i] = *(pBuf+i);
}

volatile int* get_ad() {
    return m_vi_valores;
}

#include "config.h"

#define N_PINES 6

void init_ad(int pines, int n_pines) {
    TRISB |= (pines & 0x3C) >> 2;           // AN2-AN5 -> RB0-RB3 como entradas
    TRISA |= pines & 3;                     // AN0-AN1 -> RA0-RA1 como entradas
    AD1PCFGL = ~pines;                      // pines analógicos (0 = analógico)
    AD1CSSL = pines;                        // pines que se escanean
    AD1CON3 = 0x011E;                       // SAMC = 1, ADCS = 30 -> TAD = 775 ns
    AD1CON2 = 0x0400 | ((n_pines - 1) << 2);    // CSCNA = 1, SMPI = n_pines - 1
    AD1CON1 = 0x80E4;                       // ADON, SSRC = 111, ASAM = 1
}

void get_ad(int n_pines, int *valores) {
    volatile unsigned int *pBuf = &ADC1BUF0;    // ADC1BUF0 está en 0x0300
    int i;
    IFS0bits.AD1IF = 0;
    while (!IFS0bits.AD1IF);                // espera al final del barrido
    for (i = 0; i < n_pines; i++)
        valores[i] = pBuf[i];               // ADC1BUF0 = AN0 ... ADC1BUF5 = AN5
}

int main(void) {
    int valores[N_PINES];

    InicializarReloj();
    AD1PCFGL = 0xFFFF;                      // plantilla: todo digital (init_ad lo cambia)
    PORTB = 0xFFFF;                         // LEDs apagados (activos a nivel bajo)
    TRISB = 0x0FFF;
    init_ad(0x3F, N_PINES);                 // AN0-AN5
    while (1) {
        get_ad(N_PINES, valores);
        // ... usar valores[0] (AN0) ... valores[5] (AN5) ...
    }
    return 0;
}

#include "config.h"

volatile int m_valor;       // última muestra de AN2 (RB0), compartida con la ISR

void init_ad(void) {
    TRISB |= 0x0001;            // RB0 (AN2) como entrada
    AD1PCFGL = ~0x0004;         // solo AN2 analógico
    AD1CHS0 = 2;                // CH0SA = AN2
    AD1CON3 = 0x0105;           // SAMC = 1, ADCS = 5
    AD1CON2 = 0;                // sin escaneo, SMPI = 0: interrupción en cada conversión
    AD1CON1 = 0x80E4;           // ADON, SSRC = 111, ASAM = 1 (muestreo continuo)
    IFS0bits.AD1IF = 0;         // borrar la bandera
    IPC3bits.AD1IP = 1;         // prioridad 1
    IEC0bits.AD1IE = 1;         // habilitar la interrupción del A/D
}

void __attribute__((interrupt, no_auto_psv)) _ADC1Interrupt(void) {
    IFS0bits.AD1IF = 0;
    m_valor = ADC1BUF0;         // dato de 10 bits (0 ... 1023)
}

int main(void) {
    InicializarReloj();
    AD1PCFGL = 0xFFFF;
    PORTB = 0xFFFF;             // LEDs apagados
    TRISB = 0x0FFF;             // RB12-RB15 como salidas
    init_ad();
    while (1)
        PORTB = (m_valor << 6) & 0xF000;    // bits 9-6 de la muestra -> RB15-RB12
    return 0;
}
